// ---------------------------------------------------------------------------
// qr_trail_smem: hand-written fused WY trailing with V RESIDENT in smem.
//
// The Triton fused trailing re-reads V twice (once for W=V^T A, once for the
// A-=V YT apply) and A twice; ncu shows it L2/L1-bandwidth bound at B640 (63%),
// the V/A re-reads served from L2. Triton cannot keep V resident across the two
// tl.dot calls (a resident (pheight,*) tensor spills / mis-stages). This CUDA
// kernel stages BOTH the V panel (pheight x BLK) AND the A column-tile
// (pheight x BNC) into smem ONCE, runs both WY sweeps out of smem, and writes A
// back once -- cutting the V 2nd-read AND the A 2nd-read off the L2 path.
//
// Math (exact WY block-Householder, tf32x3 for fp32 accuracy on ill-conditioned
// inputs, matching the Triton path's input_precision="tf32x3"):
//   W  = V^T @ A_tile          (BLK x BNC),  K = pheight
//   YT = T^T @ W               (BLK x BNC)
//   A_tile -= V @ YT           (pheight x BNC)
// V is Vbuf[bid][k][r] (reflector k, row r; 1 on diag, reflector below, 0 above)
// laid out row-major in r. T is Tbuf[bid] (BLK x BLK upper-tri WY factor).
//
// Tile: one CTA owns one matrix's BNC-wide column tile, ALL pheight rows.
// BLK and BNC are 32; pheight <= 512. smem floats: V(pheight*BLK) +
// A(pheight*BNC) + W(BLK*BNC) + YT(BLK*BNC) + T(BLK*BLK). For pheight=512 that
// is (512*32 + 512*32 + 32*32 + 32*32 + 32*32)*4 = 142 KB (< 228 KB optin).
// FP32 CUDA-core GEMMs (no tensor cores): the kernel is bandwidth-bound, so the
// smem-resident reuse is the win; tf32x3 emulation via hi/lo split is unneeded
// because smem fp32 math is already exact. Each thread owns a strip of W / YT
// columns and a strip of A rows; the pheight reductions read V,A from smem.
// ---------------------------------------------------------------------------
extern "C" __global__ void qr_trail_smem(
    float* __restrict__ Aptr,        // (B, N, N) row-major
    const float* __restrict__ Vptr,  // (B, BLK, N)  Vbuf[b][k][r]
    const float* __restrict__ Tptr,  // (B, BLK, BLK)
    int B, int N, int j, int pheight, int ncols, int jb,
    int BLK, int BNC)
{
    const int col_tile = blockIdx.x;
    const int bid = blockIdx.y;
    if (bid >= B) return;
    const int tid = threadIdx.x;
    const int NT = blockDim.x;

    const int c0 = col_tile * BNC;
    const int this_nc = min(BNC, ncols - c0);   // valid cols in this tile
    if (this_nc <= 0) return;

    extern __shared__ float sm[];
    float* sV = sm;                       // pheight * BLK   (sV[r*BLK + k])
    float* sA = sV + (long)pheight * BLK; // pheight * BNC   (sA[r*BNC + c])
    float* sW = sA + (long)pheight * BNC; // BLK * BNC
    float* sYT = sW + (long)BLK * BNC;    // BLK * BNC
    float* sT = sYT + (long)BLK * BNC;    // BLK * BLK

    const float* Vb = Vptr + (long)bid * BLK * N;          // Vb[k*N + r]
    const float* Tb = Tptr + (long)bid * BLK * BLK;
    float* Arow0 = Aptr + (long)bid * N * N + (long)j * N + (jb + c0); // A[j+r][jb+c0+c]

    // --- load V (pheight x BLK) into sV[r*BLK + k] ---
    for (long idx = tid; idx < (long)pheight * BLK; idx += NT) {
        int r = idx / BLK, k = idx - r * BLK;
        sV[idx] = Vb[(long)k * N + r];
    }
    // --- load A_tile (pheight x BNC) into sA[r*BNC + c] (pad cols >= this_nc with 0) ---
    for (long idx = tid; idx < (long)pheight * BNC; idx += NT) {
        int r = idx / BNC, c = idx - r * BNC;
        sA[idx] = (c < this_nc) ? Arow0[(long)r * N + c] : 0.0f;
    }
    // --- load T (BLK x BLK) into sT ---
    for (long idx = tid; idx < (long)BLK * BLK; idx += NT) sT[idx] = Tb[idx];
    __syncthreads();

    // --- W = V^T @ A_tile : W[k][c] = sum_r sV[r*BLK+k] * sA[r*BNC+c] ---
    // One thread per (k,c) pair (BLK*BNC = 1024 pairs).
    for (int p = tid; p < BLK * BNC; p += NT) {
        int k = p / BNC, c = p - k * BNC;
        float acc = 0.0f;
        for (int r = 0; r < pheight; ++r)
            acc += sV[(long)r * BLK + k] * sA[(long)r * BNC + c];
        sW[(long)k * BNC + c] = acc;
    }
    __syncthreads();

    // --- YT = T^T @ W : YT[k][c] = sum_a sT[a*BLK+k] * sW[a*BNC+c] ---
    for (int p = tid; p < BLK * BNC; p += NT) {
        int k = p / BNC, c = p - k * BNC;
        float acc = 0.0f;
        for (int a = 0; a < BLK; ++a)
            acc += sT[(long)a * BLK + k] * sW[(long)a * BNC + c];
        sYT[(long)k * BNC + c] = acc;
    }
